// The ARM32 interpreter core: register file, per-page cache of compiled basic blocks, the
// synchronous run loop, and the async call driver that suspends on host promises and yields
// between slices. Blocks are JS functions generated by arm.ts (`new Function` per block, cached
// by address); a store into a word some block covers drops that page's blocks.

import { JThread, setCurThread } from "../jvm/natives/jlang";
import { NativeFault, mem } from "./mem";
import { emitBlock, setMaxBlock } from "./arm";
import { emitThumbBlock, setMaxBlock as setMaxBlockT } from "./thumb";
import { Args, hostDispatch, hostReturn, type HostRet } from "./host";
import { RET_SENTINEL, TRAMP_BASE, TRAMP_END, PAGE_SHIFT, STACK_SIZE, MEM_SIZE } from "./abi";
import { perf } from "../perf";
export { NativeFault };

export const enum SliceExit { Budget = 0, Suspend = 1, Exit = 2 }
// ~5 ms of guest time per slice at the observed ~600M instr/s: coarse enough that the macrotask hop
// per slice is noise, fine enough that a 60 Hz frame loop on the JS thread keeps its cadence
export const SLICE_INSTR = 3_000_000;

/** a compiled block: runs, then returns the next block (F.n caches constant successors; c.look resolves the rest) */
type BlockFn = ((c: Cpu, r: Int32Array, M: typeof mem, F: BlockFn) => BlockFn) & { pc: number; n: (BlockFn | undefined)[] };
const allBlocks = new Set<BlockFn>();
/** pc reached a trampoline / the return sentinel: r[15] holds it, the run loop decides */
const STOP = ((c: Cpu) => { void c; return STOP; }) as unknown as BlockFn;
const stubs: (BlockFn | undefined)[] = new Array((TRAMP_END - TRAMP_BASE) >> 3).fill(undefined);
let retStub: BlockFn | undefined;
function stubFor(pc: number): BlockFn {
  const mk = () => { const f = ((c: Cpu) => { c.r[15] = pc; return STOP; }) as unknown as BlockFn; f.pc = pc; f.n = []; return f; };
  if (pc === RET_SENTINEL) return retStub ?? (retStub = mk());
  if (pc >= TRAMP_END) return mk();
  const i = (pc - TRAMP_BASE) >> 3;
  return stubs[i] ?? (stubs[i] = mk());
}
// dense (never sparse: a sparse JS array falls into dictionary mode and every lookup hashes)
const NPAGES = MEM_SIZE >> PAGE_SHIFT;
const pages: ((BlockFn | undefined)[] | undefined)[] = new Array(NPAGES).fill(undefined);   // ARM blocks by word
const tpages: ((BlockFn | undefined)[] | undefined)[] = new Array(NPAGES).fill(undefined);  // Thumb blocks by halfword
const cov: (Uint8Array | undefined)[] = new Array(NPAGES).fill(undefined);
export const blockStats = { compiled: 0, invalidated: 0, compileMs: 0 };
/** single-step register trace: every instruction logs pc + the registers it changed (slow; debugging only) */
export const stepMode = { on: false, ring: [] as string[], max: 40000, watch: 0, hits: [] as string[] };
export function setStepMode(on: boolean): void {
  stepMode.on = on;
  setMaxBlock(on ? 1 : 256); setMaxBlockT(on ? 1 : 256);
  for (const c of cpus) c.flush();
  stepMode.ring.length = 0;
}
const stepPrev = new Int32Array(16);
const RN = ["r0", "r1", "r2", "r3", "r4", "r5", "r6", "r7", "r8", "r9", "r10", "r11", "ip", "sp", "lr", "pc"];
export let processExited = false;
/** slice-boundary pc samples (one per SLICE_INSTR budget exit): a free statistical profile */
export const profile = { on: true, samples: new Map<number, number>() };
export function markProcessExited(): void { processExited = true; }

mem.onCodeWrite = (addr: number) => {
  const pg = addr >>> PAGE_SHIFT;
  const cv = cov[pg];
  if (cv && cv[(addr >>> 2) & 1023]) invalidatePage(pg);
};
export function invalidatePage(pg: number): void {
  const drop = (arr: (BlockFn | undefined)[] | undefined) => { if (arr) for (const f of arr) if (f) allBlocks.delete(f); };
  drop(pages[pg]); drop(tpages[pg]);
  pages[pg] = undefined;
  tpages[pg] = undefined;
  cov[pg] = undefined;
  mem.codePages[pg] = 0;
  blockStats.invalidated++;
  // every surviving block may cache a successor that lived in this page
  for (const f of allBlocks) f.n.fill(undefined);
}
/** an already-compiled block (either instruction set) for debug tooling */
export function blockAt(pc: number): unknown { return pages[pc >>> PAGE_SHIFT]?.[(pc >>> 2) & 1023] ?? tpages[pc >>> PAGE_SHIFT]?.[(pc >>> 1) & 2047]; }
export function invalidateRange(addr: number, size: number): void {
  for (let pg = addr >>> PAGE_SHIFT; pg <= (addr + size - 1) >>> PAGE_SHIFT; pg++) if (pages[pg] || tpages[pg]) invalidatePage(pg);
}

function compile(cpu: Cpu, pc: number, pg: (BlockFn | undefined)[], thumb: boolean): BlockFn {
  const t0 = performance.now();
  if (pc & (thumb ? 1 : 3)) { cpu.r[15] = pc; cpu.fault("misaligned pc"); }
  const b = thumb ? emitThumbBlock(pc) : emitBlock(pc);
  let fn: BlockFn;
  try { fn = new Function("c", "r", "M", "F", b.src + `\n//# sourceURL=wd/native/${(pc >>> 0).toString(16)}${thumb ? "t" : ""}.js`) as BlockFn; }
  catch (e) { throw new NativeFault(`[native] block compile failed at 0x${pc.toString(16)}: ${e}\n${b.src}`); }
  fn.pc = pc;
  fn.n = new Array<BlockFn | undefined>(b.slots).fill(undefined);
  allBlocks.add(fn);
  pg[thumb ? (pc >>> 1) & 2047 : (pc >>> 2) & 1023] = fn;
  const page = pc >>> PAGE_SHIFT;
  let cv = cov[page];
  if (!cv) cov[page] = cv = new Uint8Array(1024);
  cv.fill(1, (pc >>> 2) & 1023, (((b.end - 1) >>> 2) & 1023) + 1);
  mem.codePages[page] = 1;
  blockStats.compiled++;
  blockStats.compileMs += performance.now() - t0;
  return fn;
}

export class Cpu {
  r = new Int32Array(16);
  t = 0;
  n = 0; z = 0; c = 0; v = 0; q = 0; ge = 0;
  sc = 0;             // shifter carry-out of the last register-specified shift (see arm.ts op2)
  lo = 0; hi = 0;     // 64-bit multiply results
  ic = 0;             // instructions executed
  bpc = 0;            // start of the block being executed (fault attribution)
  ring = new Int32Array(64); rp = 0;
  s = new Float32Array(64);
  d = new Float64Array(this.s.buffer);
  si = new Int32Array(this.s.buffer);
  fpscr = 0;
  tlsBase = 0;
  jthread: JThread;
  tid: number;
  stackBase = 0; stackTop = 0;
  errnoAddr = 0;
  env = 0;
  tls = new Map<number, number>();
  pending: Promise<unknown> | null = null;
  exc: unknown = null;
  ret1 = 0;           // r1 at the return of the last call() (64-bit results)
  args: Args;
  name: string;
  depth = 0;
  /** guest-visible thread exit (pthread_exit / thread function returned) */
  finished = false;
  onExit: (() => void) | null = null;
  cleanup: { fn: number; arg: number }[] = [];

  constructor(jthread: JThread, name: string) {
    this.jthread = jthread;
    this.name = name;
    this.tid = ++tidSeq;
    this.args = new Args(this);
    this.tlsBase = mem.hostAlloc(256);
    this.errnoAddr = mem.hostAlloc(8);
    cpus.add(this);
  }

  ensureStack(): void {
    if (!this.stackTop) {
      const s = mem.allocStack(STACK_SIZE);
      this.stackBase = s.base; this.stackTop = s.top;
      this.r[13] = s.top;
    }
  }

  /** run guest function `fn` to completion on this Cpu (reentrant: saves and restores the register file) */
  async call(fn: number, args: (number | bigint)[] = []): Promise<number> {
    this.ensureStack();
    const r = this.r;
    const saved = new Int32Array(r);
    const st = this.t, sn = this.n, sz = this.z, scf = this.c, sv = this.v;
    const spending = this.pending;
    let n = 0;
    const stack: (number | bigint)[] = [];
    for (const a of args) {
      if (typeof a === "bigint") {
        if (n & 1) n++;
        if (n < 4) { r[n] = Number(a & 0xffffffffn) | 0; r[n + 1] = Number((a >> 32n) & 0xffffffffn) | 0; n += 2; }
        else { n = 4; stack.push(a); }
      } else if (n < 4) r[n++] = a | 0;
      else stack.push(a | 0);
    }
    // a nested call (Java → native while this Cpu is parked in a host call) builds its frame below the guest's sp
    let sp = (this.depth ? r[13] - 64 : this.stackTop) & ~7;
    if (stack.length) {
      let sz2 = 0;
      for (const a of stack) sz2 += typeof a === "bigint" ? 8 : 4;
      sp = (sp - sz2) & ~7;
      let p = sp;
      for (const a of stack) {
        if (typeof a === "bigint") { p = (p + 7) & ~7; mem.st64(p, a); p += 8; }
        else { mem.st32(p, a); p += 4; }
      }
    }
    r[13] = sp;
    r[14] = RET_SENTINEL;
    this.setPc(fn);
    this.pending = null;
    this.depth++;
    try {
      await this.run();
      this.ret1 = r[1];
      return r[0];
    } finally {
      this.depth--;
      r.set(saved);
      this.t = st; this.n = sn; this.z = sz; this.c = scf; this.v = sv;
      this.pending = spending;
    }
  }

  /** the slice driver: run until the frame returns (pc = RET_SENTINEL) or the thread finishes */
  async run(): Promise<void> {
    for (;;) {
      setCurThread(this.jthread);
      if (processExited) await new Promise<never>(() => {});
      const t0 = performance.now(), ic0 = this.ic;
      let ex: SliceExit;
      try { ex = this.runSlice(SLICE_INSTR); }
      catch (e) {
        if (e instanceof NativeFault) {
          if (!e.pc) e.pc = this.bpc >>> 0;
          if (!e.ring.length) for (let i = 1; i <= 64; i++) e.ring.push(this.ring[(this.rp + i) & 63] >>> 0);
          if (!e.message.includes("@")) e.message += ` @ ${symbolizeHook(e.pc)} (block 0x${(this.bpc >>> 0).toString(16)}, ${this.name})`;
        }
        throw e;
      } finally {
        perf.nativeMs += performance.now() - t0; perf.nativeSlices++; perf.nativeInstr += this.ic - ic0;
      }
      if (ex === SliceExit.Exit) return;
      if (ex === SliceExit.Suspend) {
        const p = this.pending!;
        this.pending = null;
        const v = await p;
        setCurThread(this.jthread);
        if (this.finished) return;
        hostReturn(this, v as HostRet);
        continue;
      }
      await yieldToLoop();
    }
  }

  /** the block for `pc` in the current instruction set (compiling it on a miss) */
  look(pc: number): BlockFn {
    if (pc >= TRAMP_BASE) return stubFor(pc);
    if (this.t) {
      let pg = tpages[pc >>> PAGE_SHIFT];
      if (pg === undefined) pg = tpages[pc >>> PAGE_SHIFT] = new Array<BlockFn | undefined>(2048).fill(undefined);
      return pg[(pc >>> 1) & 2047] ?? compile(this, pc, pg, true);
    }
    let pg = pages[pc >>> PAGE_SHIFT];
    if (pg === undefined) pg = pages[pc >>> PAGE_SHIFT] = new Array<BlockFn | undefined>(1024).fill(undefined);
    return pg[(pc >>> 2) & 1023] ?? compile(this, pc, pg, false);
  }

  runSlice(budget: number): SliceExit {
    if (stepMode.on) return this.runSliceStep(budget);
    const r = this.r;
    const limit = this.ic + budget;
    let fn = this.look(r[15]);
    for (;;) {
      fn = fn(this, r, mem, fn);
      if (fn === STOP) {
        const pc = r[15];
        if (pc === RET_SENTINEL) return SliceExit.Exit;
        if (pc >= TRAMP_END) this.fault("pc outside any module");
        hostDispatch(this, (pc - TRAMP_BASE) >> 3);
        if (this.pending) return SliceExit.Suspend;
        if (this.finished) return SliceExit.Exit;
        fn = this.look(r[15]);
      }
      if (this.ic >= limit) {
        r[15] = fn.pc;
        if (profile.on) profile.samples.set(fn.pc, (profile.samples.get(fn.pc) ?? 0) + 1);
        return SliceExit.Budget;
      }
    }
  }

  /** the tracing variant: one instruction per block, register diffs into stepMode.ring */
  runSliceStep(budget: number): SliceExit {
    const r = this.r;
    const limit = this.ic + budget;
    let fn = this.look(r[15]);
    for (;;) {
      const at = fn.pc;
      stepPrev.set(r);
      const w0 = stepMode.watch ? mem.i32[stepMode.watch >>> 2] : 0;
      fn = fn(this, r, mem, fn);
      if (at < TRAMP_BASE) {
        if (stepMode.watch && mem.i32[stepMode.watch >>> 2] !== w0) stepMode.hits.push(`${this.name} ${symbolizeHook(at)} wrote ${(mem.i32[stepMode.watch >>> 2] >>> 0).toString(16)} r0-3=${[0, 1, 2, 3].map((i) => (r[i] >>> 0).toString(16)).join(",")}\n    ` + stepMode.ring.slice(-40).join("\n    "));
        let d = "";
        for (let i = 0; i < 15; i++) if (r[i] !== stepPrev[i]) d += ` ${RN[i]}=${(r[i] >>> 0).toString(16)}`;
        stepMode.ring.push(`${this.name} ${symbolizeHook(at)}${d} [${this.n}${this.z}${this.c}${this.v}]`);
        if (stepMode.ring.length > stepMode.max) stepMode.ring.splice(0, 5000);
      }
      if (fn === STOP) {
        const pc = r[15];
        if (pc === RET_SENTINEL) return SliceExit.Exit;
        if (pc >= TRAMP_END) this.fault("pc outside any module");
        hostDispatch(this, (pc - TRAMP_BASE) >> 3);
        if (this.pending) return SliceExit.Suspend;
        if (this.finished) return SliceExit.Exit;
        fn = this.look(r[15]);
      }
      if (this.ic >= limit) { r[15] = fn.pc; return SliceExit.Budget; }
    }
  }

  setPc(addr: number): void { this.r[15] = addr & ~1; this.t = addr & 1; }
  /** interworking branch target (BX semantics): returns the pc to continue at */
  bx(addr: number): number { this.t = addr & 1; return addr & ~1; }
  flush(): void { for (let i = 0; i < NPAGES; i++) if (pages[i] || tpages[i]) invalidatePage(i); }
  cpsr(): number { return ((this.n << 31) | (this.z << 30) | (this.c << 29) | (this.v << 28) | (this.q << 27) | (this.ge << 16) | (this.t << 5) | 0x10) | 0; }
  setFlags(v: number): void { this.n = (v >>> 31) & 1; this.z = (v >>> 30) & 1; this.c = (v >>> 29) & 1; this.v = (v >>> 28) & 1; this.q = (v >>> 27) & 1; }
  /** register-specified shift with carry-out into `sc` (amount already masked to 8 bits) */
  shc(type: number, v: number, n: number): number {
    if (n === 0) { this.sc = this.c; return v; }
    switch (type) {
      case 0: if (n < 32) { this.sc = (v >>> (32 - n)) & 1; return v << n; } this.sc = n === 32 ? v & 1 : 0; return 0;
      case 1: if (n < 32) { this.sc = (v >>> (n - 1)) & 1; return v >>> n; } this.sc = n === 32 ? v >>> 31 : 0; return 0;
      case 2: if (n < 32) { this.sc = (v >>> (n - 1)) & 1; return v >> n; } this.sc = v >>> 31; return v >> 31;
      default: { const k = n & 31; if (k === 0) { this.sc = v >>> 31; return v; } this.sc = (v >>> (k - 1)) & 1; return (v >>> k) | (v << (32 - k)); }
    }
  }
  umull(a: number, b: number): void {
    a >>>= 0; b >>>= 0;
    const al = a & 0xffff, ah = a >>> 16, bl = b & 0xffff, bh = b >>> 16;
    const mid = al * bh + ah * bl;
    const lo = al * bl + (mid % 65536) * 65536;
    this.hi = (ah * bh + Math.floor(mid / 65536) + Math.floor(lo / 4294967296)) | 0;
    this.lo = lo | 0;
  }
  smull(a: number, b: number): void {
    this.umull(a, b);
    let hi = this.hi;
    if (a < 0) hi = (hi - b) | 0;
    if (b < 0) hi = (hi - a) | 0;
    this.hi = hi;
  }
  /** (hi:lo) += (h:l) */
  add64(l: number, h: number): void {
    const s = (this.lo >>> 0) + (l >>> 0);
    this.lo = s | 0;
    this.hi = (this.hi + h + (s > 4294967295 ? 1 : 0)) | 0;
  }
  /** EABI syscall (swi 0, number in r7): only what a userspace runtime issues directly */
  swi(): void {
    const r = this.r;
    switch (r[7] >>> 0) {
      case 0xf0002: invalidateRange(r[0] >>> 0, (r[1] - r[0]) >>> 0); r[0] = 0; return;   // __ARM_NR_cacheflush
      case 0xf0005: this.tlsBase = r[0]; r[0] = 0; return;                                   // __ARM_NR_set_tls
      case 20: r[0] = 4242; return;                                                          // getpid
      case 224: r[0] = 4242 + this.tid; return;                                              // gettid
      default: this.fault(`swi: unsupported syscall ${r[7] >>> 0}`);
    }
  }
  /** round to nearest, ties to even (the default FPSCR rounding mode for VCVT) */
  rne(x: number): number {
    const f = Math.floor(x), d = x - f;
    return d < 0.5 ? f : d > 0.5 ? f + 1 : (f % 2 === 0 ? f : f + 1);
  }
  sat(v: number): number { if (v > 2147483647) { this.q = 1; return 2147483647; } if (v < -2147483648) { this.q = 1; return -2147483648; } return v | 0; }
  fault(msg: string): never {
    const e = new NativeFault(`[native] ${msg} @ ${symbolizeHook(this.r[15] >>> 0)} (${this.name})`);
    e.pc = this.r[15] >>> 0;
    for (let i = 1; i <= 64; i++) e.ring.push(this.ring[(this.rp + i) & 63] >>> 0);
    throw e;
  }
}

let tidSeq = 0;
export const cpus = new Set<Cpu>();
const byThread = new WeakMap<JThread, Cpu>();

export function cpuFor(t: JThread): Cpu {
  let c = byThread.get(t);
  if (!c) { c = new Cpu(t, t.jname); byThread.set(t, c); }
  return c;
}
export function bindCpu(t: JThread, c: Cpu): void { byThread.set(t, c); }
export function cpuByTid(tid: number): Cpu | undefined { for (const c of cpus) if (c.tid === tid) return c; return undefined; }

export let symbolizeHook: (pc: number) => string = (pc) => "0x" + pc.toString(16);
export function setSymbolizeHook(f: (pc: number) => string): void { symbolizeHook = f; }

// A macrotask boundary so the main looper, rAF and other cooperative threads get the JS thread.
// MessageChannel is not subject to the nested-setTimeout clamp.
const chan = typeof MessageChannel !== "undefined" ? new MessageChannel() : null;
const waiters: (() => void)[] = [];
if (chan) {
  chan.port1.onmessage = () => { const w = waiters.splice(0); for (const f of w) f(); };
  // an open port keeps a bun/node process alive after its work is done (tests, scripts)
  (chan.port1 as unknown as { unref?: () => void }).unref?.();
}
export function yieldToLoop(): Promise<void> {
  if (!chan) return new Promise((r) => setTimeout(r, 0));
  return new Promise((r) => { if (waiters.push(r) === 1) chan.port2.postMessage(0); });
}
